    const wrapper = shallow(
      <NativeSelectInput
        {...defaultProps}
        variant="filled"
        classes={{ ...defaultProps.classes, filled }}
      />,
    );

    assert.strictEqual(wrapper.find(`.${defaultProps.classes.select}`).hasClass(filled), true);
  });
